import { backoffPolicy } from "./retry.js";

const DEFAULT_TIMEOUT = 2500;

// fetches a page of records; backoffPolicy controls backoff between attempts
export const policy = backoffPolicy({
  maxAttempts: 5,
  baseDelayMs: 50,
});

export async function fetchPage(client, cursor) {
  return client.get("/records", { cursor, timeout: DEFAULT_TIMEOUT });
}
import { test } from "node:test";
import assert from "node:assert/strict";
import { backoffPolicy } from "../src/retry.js";

test("every module exposes a usable policy", async () => {
  const mods = await Promise.all([
  import("../src/m01.js"),
  import("../src/m02.js"),
  import("../src/m03.js"),
  import("../src/m04.js"),
  import("../src/m05.js"),
  import("../src/m06.js"),
  import("../src/m07.js"),
  import("../src/m08.js"),
  import("../src/m09.js"),
  import("../src/m10.js"),
  import("../src/m11.js"),
  import("../src/m12.js"),
  ]);
  for (const m of mods) {
    assert.equal(typeof m.policy.delayFor, "function");
    assert.equal(m.policy.delayFor(m.policy.maxAttempts), null);
  }
  assert.equal(typeof backoffPolicy, "function");
});

